32	#define checkRuntime(call) check_runtime(call, #call, __LINE__, __FILE__)
33	
34	inline static bool check_runtime(cudaError_t e, const char *call, int line, const char *file)
35	{
36	    if (e != cudaSuccess)
37	    {
38	        fprintf(stderr, "CUDA Runtime error %s # %s, code = %s [ %d ] in file %s:%d\n", call, cudaGetErrorString(e),
39	                cudaGetErrorName(e), e, file, line);
40	        return false;
41	    }
42	    return true;
43	}
