53	NVCVPointI pytopoint(py::tuple point)
54	{
55	    if (point.size() > 2 || point.empty())
56	        throw py::value_error("Invalid point size.");
57	
58	    NVCVPointI ret;
59	    memset(&ret, 0, sizeof(ret));
60	
61	    if (!point.empty())
62	    {
63	        ret.x = point[0].cast<int>();
64	    }
65	    if (point.size() > 1)
66	    {
67	        ret.y = point[1].cast<int>();
68	    }
69	    return ret;
70	}
71	
72	NVCVBoxI pytobox(py::tuple box)
73	{
74	    if (box.size() > 4 || box.empty())
75	        throw py::value_error("Invalid box size.");
76	
77	    NVCVBoxI ret;
78	    memset(&ret, 0, sizeof(ret));
79	
80	    if (!box.empty())
81	    {
82	        ret.x = box[0].cast<int>();
83	    }
84	    if (box.size() > 1)
85	    {
86	        ret.y = box[1].cast<int>();
87	    }
88	    if (box.size() > 2)
89	    {
90	        ret.width = box[2].cast<int>();
91	    }
92	    if (box.size() > 3)
93	    {
94	        ret.height = box[3].cast<int>();
95	    }
96	    return ret;
97	}
98	
99	NVCVColorRGBA pytocolor(py::tuple color)
100	{
101	    if (color.size() > 4 || color.empty())
102	        throw py::value_error("Invalid color size.");
103	
104	    NVCVColorRGBA ret;
105	    memset(&ret, 0, sizeof(ret));
106	    ret.a = 255;
107	
108	    auto *pr = reinterpret_cast<std::byte *>(&ret);
109	    for (size_t i = 0; i < color.size(); ++i)
110	    {
111	        pr[i] = static_cast<std::byte>(color[i].cast<unsigned char>());
112	    }
113	    return ret;
114	}
