116	// Inverse of pytopoint/pytobox/pytocolor.  Used for `def_property_readonly`
117	// accessors so pybind11-stubgen sees a Python-importable `tuple` instead of
118	// raw C-API type names like `NVCVPointI`.
119	py::tuple pointtotuple(const NVCVPointI &p)
120	{
121	    return py::make_tuple(p.x, p.y);
122	}
123	
124	py::tuple boxtotuple(const NVCVBoxI &b)
125	{
126	    return py::make_tuple(b.x, b.y, b.width, b.height);
127	}
128	
129	py::tuple colortotuple(const NVCVColorRGBA &c)
130	{
131	    return py::make_tuple(c.r, c.g, c.b, c.a);
132	}
