49	nvcv::TensorShape InterleavedShapeForOSD(const nvcv::TensorDataStridedCuda &data, const char *tensorName)
50	{
51	    auto access = nvcv::TensorDataAccessStridedImagePlanar::Create(data);
52	    if (!access)
53	    {
54	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "%s must be an image-like planar tensor",
55	                              tensorName);
56	    }
57	
58	    if (data.layout() == nvcv::TENSOR_NCHW)
59	    {
60	        return nvcv::TensorShape{
61	            {access->numSamples(), access->numRows(), access->numCols(), access->numChannels()},
62	            "NHWC"
63	        };
64	    }
65	    if (data.layout() == nvcv::TENSOR_CHW)
66	    {
67	        return nvcv::TensorShape{
68	            {access->numRows(), access->numCols(), access->numChannels()},
69	            "HWC"
70	        };
71	    }
72	
73	    throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
74	                          "Input/output must have NCHW or CHW layout for planar OSD adaptation");
75	}
