84	OSDPlanarBridgeWorkspace::~OSDPlanarBridgeWorkspace()
85	{
86	    if (m_ready == nullptr)
87	    {
88	        return;
89	    }
90	    if (m_pending)
91	    {
92	        NVCV_CHECK_LOG(cudaEventSynchronize(m_ready));
93	    }
94	    NVCV_CHECK_LOG(cudaEventDestroy(m_ready));
95	}
