102	OSDPlanarBridgeTensors OSDPlanarBridgeWorkspace::prepare(cudaStream_t stream, const nvcv::Tensor &input,
103	                                                         const nvcv::TensorDataStridedCuda &inputData,
104	                                                         const nvcv::TensorDataStridedCuda &outputData,
105	                                                         Reformat                          &reformat)
106	{
107	    const std::array<nvcv::TensorShape, kBridgeTensorCount> targetShapes{
108	        InterleavedShapeForOSD(inputData, "Input"),
109	        InterleavedShapeForOSD(outputData, "Output"),
110	    };
111	
112	    synchronizeIfNeeded(stream, targetShapes, inputData.dtype());
113	    for (int which : {kInputIndex, kOutputIndex})
114	    {
115	        resizeBuffer(which, targetShapes[which], inputData.dtype());
116	    }
117	
118	    reformat(stream, input, m_interleaved[kInputIndex]);
119	
120	    auto inputBridge  = m_interleaved[kInputIndex].exportData<nvcv::TensorDataStridedCuda>();
121	    auto outputBridge = m_interleaved[kOutputIndex].exportData<nvcv::TensorDataStridedCuda>();
122	    if (!inputBridge || !outputBridge)
123	    {
124	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
125	                              "Internal OSD reformat tensors must be cuda-accessible");
126	    }
127	
128	    return {*inputBridge, *outputBridge};
129	}
