131	void OSDPlanarBridgeWorkspace::finish(cudaStream_t stream, const nvcv::Tensor &output, Reformat &reformat)
132	{
133	    reformat(stream, m_interleaved[kOutputIndex], output);
134	    markPending(stream);
135	}
