143	void OSDPlanarBridgeWorkspace::synchronizeIfNeeded(
144	    cudaStream_t stream, const std::array<nvcv::TensorShape, kBridgeTensorCount> &targetShapes, nvcv::DataType dtype)
145	{
146	    if (!m_pending)
147	    {
148	        return;
149	    }
150	
151	    bool shapeOrTypeChanged = false;
152	    for (int which : {kInputIndex, kOutputIndex})
153	    {
154	        const nvcv::Tensor &tensor = m_interleaved[which];
155	        shapeOrTypeChanged |= !tensor || tensor.shape() != targetShapes[which] || tensor.dtype() != dtype;
156	    }
157	
158	    if (shapeOrTypeChanged)
159	    {
160	        NVCV_CHECK_THROW(cudaEventSynchronize(m_ready));
161	        m_pending = false;
162	    }
163	    else
164	    {
165	        NVCV_CHECK_THROW(cudaStreamWaitEvent(stream, m_ready));
166	    }
167	}
