169	void OSDPlanarBridgeWorkspace::resizeBuffer(int which, const nvcv::TensorShape &shape, nvcv::DataType dtype)
170	{
171	    nvcv::Tensor &tensor = m_interleaved[which];
172	    if (!tensor || tensor.shape() != shape || tensor.dtype() != dtype)
173	    {
174	        tensor = nvcv::Tensor(shape, dtype);
175	    }
176	}
