193	void OSD::operator()(cudaStream_t stream, const nvcv::Tensor &in, const nvcv::Tensor &out,
194	                     const NVCVElements &elements) const
195	{
196	    CVCUDA_NVTX_RANGE("cvcuda::OSD::operator()[Tensor]");
197	    auto inData = in.exportData<nvcv::TensorDataStridedCuda>();
198	    if (inData == nullptr)
199	    {
200	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
201	                              "Input must be cuda-accessible, pitch-linear tensor");
202	    }
203	
204	    auto outData = out.exportData<nvcv::TensorDataStridedCuda>();
205	    if (outData == nullptr)
206	    {
207	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
208	                              "Output must be cuda-accessible, pitch-linear tensor");
209	    }
210	
211	    const bool inPlanar = IsOSDPlanarLayout(inData->layout());
212	
213	    if (const bool outPlanar = IsOSDPlanarLayout(outData->layout()); inPlanar || outPlanar)
214	    {
215	        if (!inPlanar || !outPlanar || inData->layout() != outData->layout())
216	        {
217	            throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
218	                                  "Input and output layouts must both be NCHW or both be CHW for planar OSD");
219	        }
220	
221	        auto                  &workspace = m_planarWorkspace.get();
222	        auto                   lock      = workspace.lock();
223	        OSDPlanarBridgeTensors bridged   = workspace.prepare(stream, in, *inData, *outData, *m_reformatOp);
