103	{
104	    float length         = std::sqrt((float)((y1 - y0) * (y1 - y0) + (x1 - x0) * (x1 - x0)));
105	    float angle          = std::atan2((float)y1 - y0, (float)x1 - x0);
106	    float cos_angle      = std::cos(angle);
107	    float sin_angle      = std::sin(angle);
108	    float half_thickness = thickness / 2.0f;
109	
110	    // upline
111	    // a    b
112	    // d    c
113	    auto cmd         = std::make_shared<RectangleCommand>();
114	    cmd->batch_index = batch_idx;
115	    cmd->ax1         = -half_thickness * cos_angle + x0 - sin_angle * half_thickness;
116	    cmd->ay1         = -half_thickness * sin_angle + cos_angle * half_thickness + y0;
117	    cmd->bx1         = (length + half_thickness) * cos_angle - sin_angle * half_thickness + x0;
118	    cmd->by1         = (length + half_thickness) * sin_angle + cos_angle * half_thickness + y0;
119	    cmd->dx1         = -half_thickness * cos_angle + x0 + sin_angle * half_thickness;
