138	    // b   c
139	    cmd->bounding_left   = min(min(min(cmd->ax1, cmd->bx1), cmd->cx1), cmd->dx1);
140	    cmd->bounding_right  = ceil(max(max(max(cmd->ax1, cmd->bx1), cmd->cx1), cmd->dx1));
141	    cmd->bounding_top    = min(min(min(cmd->ay1, cmd->by1), cmd->cy1), cmd->dy1);
