251	    if (words.empty() || font_size <= 0)
252	        return;
253	
254	    // Scale to 3x, in order to align with nvOSD effect
255	    font_size = context->text_backend->uniform_font_size(font_size);
256	    font_size = std::max(10, std::min(MAX_FONT_SIZE, font_size));
257	
