268	                             *(cuOSDColor *)(&bgColor), {0, 0, 0, 0});
269	    }
270	    context->commands.emplace_back(std::make_shared<TextHostCommand>(batch_idx, words, font_size, font, x + xmargin,
271	                                                                     y + ymargin - yoffset, borderColor.r,
272	                                                                     borderColor.g, borderColor.b, borderColor.a));
