299	            text_cmd->gputile.bounding_bottom = text_cmd->y + text_cmd->font_size;
300	            text_cmd->gputile.bounding_top    = text_cmd->gputile.bounding_bottom;
301	
302	            auto glyph_map = context->text_backend->query(text_cmd->font_name.c_str(), text_cmd->font_size);
303	            if (glyph_map == nullptr)
304	                continue;
305	
306	            std::vector<TextLocation> textline_locations;
307	            int                       max_glyph_height = 0;
308	            for (auto &word : text_cmd->text)
309	            {
310	                auto meta = glyph_map->query(word);
311	                if (meta == nullptr)
312	                    continue;
313	
314	                max_glyph_height = max(max_glyph_height, meta->height());
315	            }
316	
317	            for (auto &word : text_cmd->text)
318	            {
319	                auto meta = glyph_map->query(word);
