402	static void cuosd_apply(cuOSDContext_t context, int width, int height, int batch, cuOSDImageFormat format,
403	                        cudaStream_t stream)
404	{
405	    if (context->commands.empty())
406	    {
407	        LOG_WARNING("Please check if there is anything to draw.\n");
408	        return;
409	    }
410	
411	    if (!context->commands.empty())
412	    {
413	        cuosd_text_prepare(context, width, height, stream);
414	
415	        context->bounding_left   = width;
416	        context->bounding_top    = height;
417	        context->bounding_right  = 0;
418	        context->bounding_bottom = 0;
419	
420	        size_t           byte_of_commands = 0;
421	        int              text_line        = 0;
422	        const int        num_commands     = context->commands.size();
423	        std::vector<int> cmd_offset(num_commands + batch + 1);
424	        for (int i = 0; i < (int)context->commands.size(); ++i)
425	        {
426	            auto &cmd     = context->commands[i];
427	            cmd_offset[i] = byte_of_commands;
428	            cmd->reserved = text_line;
429	
430	            context->bounding_left   = min(context->bounding_left, cmd->bounding_left);
431	            context->bounding_top    = min(context->bounding_top, cmd->bounding_top);
432	            context->bounding_right  = max(context->bounding_right, cmd->bounding_right);
433	            context->bounding_bottom = max(context->bounding_bottom, cmd->bounding_bottom);
434	
435	            if (cmd->type == CommandType::Text)
436	            {
437	                auto text_cmd              = std::static_pointer_cast<TextHostCommand>(cmd);
438	                text_cmd->gputile.reserved = text_line;
439	                if (text_cmd->gputile.type == CommandType::Text)
440	                    ++text_line;
441	                byte_of_commands += sizeof(TextCommand);
442	            }
443	            else if (cmd->type == CommandType::Rectangle)
444	                byte_of_commands += sizeof(RectangleCommand);
445	            else if (cmd->type == CommandType::Circle)
446	                byte_of_commands += sizeof(CircleCommand);
447	            else if (cmd->type == CommandType::Segment)
448	                byte_of_commands += sizeof(SegmentCommand);
449	            else if (cmd->type == CommandType::PolyFill)
450	                byte_of_commands += sizeof(PolyFillCommand);
451	        }
452	
453	        int command_index = 0;
454	        for (int batch_index = 0; batch_index <= batch; ++batch_index)
455	        {
456	            while (command_index < num_commands && context->commands[command_index]->batch_index < batch_index)
457	                ++command_index;
458	            cmd_offset[num_commands + batch_index] = command_index;
459	        }
460	
461	        if (context->gpu_commands == nullptr)
462	            context->gpu_commands = std::make_unique<Memory<unsigned char>>();
463	        if (context->gpu_commands_offset == nullptr)
464	            context->gpu_commands_offset = std::make_unique<Memory<int>>();
465	
466	        context->gpu_commands->alloc_or_resize_to(byte_of_commands);
467	        context->gpu_commands_offset->alloc_or_resize_to(cmd_offset.size());
468	        memcpy(context->gpu_commands_offset->host(), cmd_offset.data(), sizeof(int) * cmd_offset.size());
469	
470	        for (int i = 0; i < (int)context->commands.size(); ++i)
471	        {
472	            auto          &cmd    = context->commands[i];
473	            unsigned char *pg_cmd = context->gpu_commands->host() + cmd_offset[i];
474	
475	            if (cmd->type == CommandType::Text)
476	            {
477	                memcpy(pg_cmd, (&(std::static_pointer_cast<TextHostCommand>(cmd)->gputile)), sizeof(TextCommand));
478	            }
479	            else if (cmd->type == CommandType::Rectangle)
480	            {
481	                memcpy(pg_cmd, cmd.get(), sizeof(RectangleCommand));
482	            }
483	            else if (cmd->type == CommandType::Circle)
484	            {
485	                memcpy(pg_cmd, cmd.get(), sizeof(CircleCommand));
486	            }
487	            else if (cmd->type == CommandType::Segment)
488	            {
489	                memcpy(pg_cmd, cmd.get(), sizeof(SegmentCommand));
490	            }
491	            else if (cmd->type == CommandType::PolyFill)
492	            {
493	                memcpy(pg_cmd, cmd.get(), sizeof(PolyFillCommand));
494	            }
495	        }
496	        context->gpu_commands->copy_host_to_device(stream);
497	        context->gpu_commands_offset->copy_host_to_device(stream);
498	    }
