612	// external_msaa4x:
613	// check if given coordinate is on border or outside the border, do msaa4x for border pixels
614	static __device__ __forceinline__ bool external_msaa4x(float ix, float iy, float ax, float ay, float bx, float by,
615	                                                       float cx, float cy, float dx, float dy, unsigned char a,
616	                                                       unsigned char &alpha)
617	{
618	    bool h0 = !inbox_single_pixel(ix - 0.25f, iy - 0.25f, ax, ay, bx, by, cx, cy, dx, dy);
619	    bool h1 = !inbox_single_pixel(ix + 0.25f, iy - 0.25f, ax, ay, bx, by, cx, cy, dx, dy);
620	    bool h2 = !inbox_single_pixel(ix + 0.25f, iy + 0.25f, ax, ay, bx, by, cx, cy, dx, dy);
621	    bool h3 = !inbox_single_pixel(ix - 0.25f, iy + 0.25f, ax, ay, bx, by, cx, cy, dx, dy);
622	    if (h0 || h1 || h2 || h3)
623	    {
624	        if (h0 && h1 && h2 && h3)
625	            return true;
626	        alpha = a * (h0 + h1 + h2 + h3) * 0.25f;
627	        return true;
628	    }
629	    return false;
630	}
