749	// interpolation_fn:
750	// interpolate alpha for border pixels
751	static __device__ unsigned char interpolation_fn(float x, int a, int b, int padding, unsigned char origin_alpha)
752	{
753	    int x0 = a - padding < 0 ? 0 : a - padding;
754	    int x1 = b + padding;
755	    if (x < x0 || x > x1)
756	        return 0;
757	    if (x >= a && x < b)
758	        return origin_alpha;
759	    if (x >= b && x <= x1)
760	        return (x1 - x) / padding * origin_alpha;
761	    if (x < a && x >= x0)
762	        return (x - x0) / padding * origin_alpha;
763	    return 0;
764	}
