766	// render_circle_interpolation:
767	// render cicle with border interpolation
768	static __device__ void render_circle_interpolation(int ix, int iy, CircleCommand *p, uchar4 color[4])
769	{
770	    float tr0 = sqrt((float)(ix - p->cx) * (ix - p->cx) + (iy - p->cy) * (iy - p->cy));
771	    float tr1 = sqrt((float)(ix + 1 - p->cx) * (ix + 1 - p->cx) + (iy - p->cy) * (iy - p->cy));
772	    float tr2 = sqrt((float)(ix - p->cx) * (ix - p->cx) + (iy + 1 - p->cy) * (iy + 1 - p->cy));
773	    float tr3 = sqrt((float)(ix + 1 - p->cx) * (ix + 1 - p->cx) + (iy + 1 - p->cy) * (iy + 1 - p->cy));
774	
775	    int inner_boundsize    = p->radius - p->thickness / 2;
776	    int external_boundsize = inner_boundsize + p->thickness;
777	
778	    if (p->thickness < 0)
779	    {
780	        if (p->thickness == -1)
781	        {
782	            external_boundsize = p->radius;
783	        }
784	        else
785	        {
786	            external_boundsize = inner_boundsize;
787	        }
788	        inner_boundsize = 0;
789	    }
790	
791	    unsigned char alpha0 = interpolation_fn(tr0, inner_boundsize, external_boundsize, 1, p->c3);
792	    unsigned char alpha1 = interpolation_fn(tr1, inner_boundsize, external_boundsize, 1, p->c3);
793	    unsigned char alpha2 = interpolation_fn(tr2, inner_boundsize, external_boundsize, 1, p->c3);
794	    unsigned char alpha3 = interpolation_fn(tr3, inner_boundsize, external_boundsize, 1, p->c3);
795	
796	    if (alpha0)
797	    {
798	        blend_single_color(color[0], p->c0, p->c1, p->c2, alpha0);
799	    }
800	    if (alpha1)
801	    {
802	        blend_single_color(color[1], p->c0, p->c1, p->c2, alpha1);
803	    }
804	    if (alpha2)
805	    {
806	        blend_single_color(color[2], p->c0, p->c1, p->c2, alpha2);
807	    }
808	    if (alpha3)
809	    {
810	        blend_single_color(color[3], p->c0, p->c1, p->c2, alpha3);
811	    }
812	}
