814	static __device__ void sample_pixel_bilinear(float *d_ptr, int x, int y, float sx, float sy, int width, int height,
815	                                             float threshold, unsigned char &a)
816	{
817	    float src_x  = (x + 0.5f) * sx - 0.5f;
818	    float src_y  = (y + 0.5f) * sy - 0.5f;
819	    int   y_low  = floorf(src_y);
820	    int   x_low  = floorf(src_x);
821	    int   y_high = limit(y_low + 1, 0, height - 1);
822	    int   x_high = limit(x_low + 1, 0, width - 1);
823	    y_low        = limit(y_low, 0, height - 1);
824	    x_low        = limit(x_low, 0, width - 1);
825	
826	    int ly = rint((src_y - y_low) * INTER_RESIZE_COEF_SCALE);
827	    int lx = rint((src_x - x_low) * INTER_RESIZE_COEF_SCALE);
828	    int hy = INTER_RESIZE_COEF_SCALE - ly;
829	    int hx = INTER_RESIZE_COEF_SCALE - lx;
830	
831	    uchar4 _scr;
832	
833	    _scr.x = d_ptr[x_low + y_low * width] > threshold ? 127 : 0;
834	    _scr.y = d_ptr[x_high + y_low * width] > threshold ? 127 : 0;
835	    _scr.z = d_ptr[x_low + y_high * width] > threshold ? 127 : 0;
836	    _scr.w = d_ptr[x_high + y_high * width] > threshold ? 127 : 0;
837	
838	    a = (((hy * ((hx * _scr.x + lx * _scr.y) >> 4)) >> 16) + ((ly * ((hx * _scr.z + lx * _scr.w) >> 4)) >> 16) + 2)
839	     >> 2;
840	}
